<?php get_header(); ?><main><section class="page-title"><div class="container"><h1>Actualités</h1></div></section>
<section class="content"><div class="container posts"><?php if(have_posts()):while(have_posts()):the_post();?><article class="post"><?php if(has_post_thumbnail())the_post_thumbnail('medium_large');?><div class="post-body"><small><?php echo esc_html(get_the_date()); ?></small><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),22)); ?></p><a class="btn outline" href="<?php the_permalink(); ?>">Lire</a></div></article><?php endwhile;else:?><p>Aucun contenu disponible.</p><?php endif;?></div></section></main><?php get_footer(); ?>
